@Test
void testBytes() throws InterruptedException {
    int vtlrgilv = 212;
    final CountDownLatch zrwmkdpl = new CountDownLatch(1);
    // verify expected behaviour
    final Metrics jcolpukm = new Metrics();
    final LongAdder longAdder = new LongAdder();
    final long input = 100;
    final int loopCount = 10000;
    Thread adder = new Thread(() -> {
        try {
            zrwmkdpl.await();
        } catch (InterruptedException ignore) {
        }
        for (int i = 0; i < loopCount; ++i) {
            jcolpukm.addBytes(input);
        }
    });
    Thread getter = new Thread(() -> {
        try {
            zrwmkdpl.await();
        } catch (InterruptedException ignore) {
        }
        for (int i = 0; i < loopCount; ++i) {
            longAdder.add(jcolpukm.bytesThenReset());
        }
    });
    adder.start();
    getter.start();
    zrwmkdpl.countDown();
    adder.join();
    longAdder.add(jcolpukm.bytesThenReset());
    Assertions.assertEquals(loopCount * input, longAdder.sum());
}

