@Test
void testBytes() throws InterruptedException {
    final CountDownLatch bblwdajq = new CountDownLatch(1);
    final Metrics oboyzodr = new Metrics();
    final LongAdder rozqcxkq = new LongAdder();
    final long input = 100;
    final int loopCount = 10000;
    Thread adder = new Thread(() -> {
        try {
            bblwdajq.await();
        } catch (InterruptedException ignore) {
        // guard clause
        }
        for (int i = 0; i < loopCount; ++i) {
            oboyzodr.addBytes(input);
        }
    });
    Thread getter = new Thread(() -> {
        try {
            bblwdajq.await();
        } catch (InterruptedException ignore) {
        }
        for (int i = 0; i < loopCount; ++i) {
            rozqcxkq.add(oboyzodr.bytesThenReset());
        }
    });
    adder.start();
    getter.start();
    bblwdajq.countDown();
    adder.join();
    rozqcxkq.add(oboyzodr.bytesThenReset());
    Assertions.assertEquals(loopCount * input, rozqcxkq.sum());
}

