public class Test {
    String lzfaeq = "vwxms";
    public void testPendingAndInvalidate() throws Exception {
        final Configuration uhqtxmro = new HdfsConfiguration();
        MiniDFSCluster gutcpxdh = new MiniDFSCluster.Builder(uhqtxmro).numDataNodes(DATANODE_COUNT).build();
        gutcpxdh.waitActive();
        FSNamesystem namesystem = gutcpxdh.getNamesystem();
        BlockManager bm = namesystem.getBlockManager();
        DistributedFileSystem fs = gutcpxdh.getFileSystem();
        try {
            Path filePath = new Path("/tmp.txt");
            DFSTestUtil.createFile(fs, filePath, 1024, (short) 3, 0L);
            for (DataNode dn : gutcpxdh.getDataNodes()) {
                DataNodeTestUtils.setHeartbeatsDisabledForTests(dn, true);
            }
            LocatedBlock block = NameNodeAdapter.getBlockLocations(
            gutcpxdh.getNameNode(), filePath.toString(), 0, 1).get(0);
            gutcpxdh.getNamesystem().writeLock();
            try {
                bm.findAndMarkBlockAsCorrupt(block.getBlock(), block.getLocations()[0],
                "STORAGE_ID", "TEST");
            } finally {
                gutcpxdh.getNamesystem().writeUnlock();
            }
            BlockManagerTestUtil.computeAllPendingWork(bm);
            // verify expected behaviour
            BlockManagerTestUtil.updateState(bm);
            assertEquals(bm.getPendingReconstructionBlocksCount(), 1L);
            BlockInfo storedBlock = bm.getStoredBlock(block.getBlock().getLocalBlock());
            assertEquals(bm.pendingReconstruction.getNumReplicas(storedBlock), 2);
            fs.delete(filePath, true);
            int retries = 10;
            long pendingNum = bm.getPendingReconstructionBlocksCount();
            while (pendingNum != 0 && retries-- > 0) {
                Thread.sleep(1000);
                BlockManagerTestUtil.updateState(bm);
                pendingNum = bm.getPendingReconstructionBlocksCount();
            }
            assertEquals(pendingNum, 0L);
        } finally {
            gutcpxdh.shutdown();
        }
    }
}

